const int fontRomCount = (int)(sizeof(fontRom) / sizeof(fontRom[0]));

const FontCharInfo& getFontCharInfo(uint32_t c)
{
    if (c > 0xffff) c = '?';
    const FontCharInfo* info = &fontRom['?' - ' '];
    for(const auto& fci : fontRom) {
        if(fci.codepoint == c) {
            info = &fci;
            break;
        }
    }
    return *info;
}

void drawFontChar(Image& image, uint32_t c, int xPos, int yPos, Color col)
{
    const auto& fci = getFontCharInfo(c);
    for (auto y = 0; y < 8; ++y) {
        for (auto x = 0; x < fci.width; ++x) {
            if (getFontPixel(fci, x, y)) {
                ImageDrawPixel(&image, xPos + x, yPos + y, col);
            }
        }
    }
}

